// Smooth Motion: generate frames for the display refresh rate or a fixed
// target. Frames are generated by libavfilter's framerate filter, which blends
// neighbouring frames (linear interpolation). The plugin publishes its
// readings as a page in Luma's native Stats panel.
//
// Player-specific choices:
//  - framerate instead of minterpolate: the blend-only path of minterpolate
//    costs about four times more CPU at 1080p and is single-threaded, while
//    framerate is slice-threaded; both produce the same linear blend.
//  - the target uses the exact display rate (159.96, not 160) so generated
//    frames do not drift against the compositor.
//  - the filter is added when the file is opened, before mpv builds the video
//    chain, so playback never has to be reconfigured after it started.
//  - hardware decoding is paused for as long as the plugin is enabled (not
//    per toggle): the filter cannot consume GPU frames, and switching hwdec
//    at runtime makes mpv restart the decoder with a seek. Toggling
//    interpolation then only adds or removes the filter.

let luma;
let active = false;
let original = {};
let hwdecForced = false;
let hwdecPin = "";
let pinCheckAt = 0;
let lastTarget = 0;
let filterActive = false;
let filterVerified = false;
let statusText = "";
let statsPageError = "";
let appliedSignature = "";
let pendingTarget = 0;
let pendingSince = 0;
let verifyStartedAt = 0;
let dropSample = null;
let droppedPerSecond = 0;
let retries = 0;

function remember(key) {
    const value = luma.mpv.getProperty(key);
    if (value !== undefined && value !== null && value !== "")
        original[key] = value;
}

function restore(key) {
    if (original[key] !== undefined)
        luma.mpv.setProperty(key, original[key]);
}

// The stats snapshot carries the observed values, so the plugin can avoid
// synchronous mpv property reads on the GUI thread — at file open those block
// the loadfile and can cost the first frames.
function snapshotValue(name) {
    const snapshot = luma.stats.snapshot();
    const value = snapshot[name];
    return value === undefined || value === null ? "" : String(value).trim();
}

function hwdecName() {
    return snapshotValue("hwdec-current").toLowerCase();
}

function removeFilter() {
    // The old label is kept for users upgrading from an earlier plugin build.
    // mpv reports an error for a label that is not in the chain; the caller
    // only removes while it believes a filter is active.
    for (const label of ["@luma-fps", "@lumafps"])
        luma.mpv.command(["vf", "remove", label]);
}

function configBool(key, fallback) {
    const value = luma.config.get(key, fallback);
    if (value === true || value === 1)
        return true;
    if (value === false || value === 0 || value === null || value === undefined)
        return false;
    const text = String(value).toLowerCase();
    return text === "true" || text === "1";
}

function displayFps(snapshot) {
    const mpvFps = Number(snapshot["display-fps"]);
    if (mpvFps > 1)
        return mpvFps;
    const screenFps = Number(snapshot["screen-refresh-rate"]);
    return screenFps > 1 ? screenFps : 0;
}

// Match the compositor exactly instead of rounding to 160: generating 160
// frames per second for a 159.96 Hz display makes mpv drop a frame every ~25
// seconds.
function targetFps(snapshot) {
    const mode = String(luma.config.get("mode", "display"));
    if (mode !== "display")
        return Math.max(1, Number(mode));
    const display = displayFps(snapshot);
    return display > 1 ? Math.round(display * 100) / 100 : 60;
}

function formatFps(value) {
    const number = Number(value);
    return number > 0 ? number.toFixed(2) : "n/a";
}

// Hardware decoding hands cuda/vaapi frames to the filter chain; "*-copy"
// decoders already produce software frames.
function softwareFrames() {
    const hwdec = hwdecName();
    return hwdec === "" || hwdec === "no" || hwdec.endsWith("-copy");
}

function buildFilter(target) {
    return "@lumafps:framerate=fps=" + target;
}

function addFilter(target) {
    pendingTarget = 0;
    verifyStartedAt = Date.now();
    dropSample = null;
    droppedPerSecond = 0;
    filterActive = luma.mpv.command(["vf", "add", buildFilter(target)]);
    filterVerified = false;
    if (!filterActive)
        statusText = luma.i18n.t("mpv rejected the filter; see the mpv log");
}

function isAutoHwdec(value) {
    const mode = String(value).toLowerCase();
    return mode === "" || mode === "auto" || mode === "auto-safe"
        || mode === "auto-copy" || mode === "auto-copy-safe"
        || mode === "auto-unsafe" || mode === "auto-copy-unsafe"
        || mode === "yes";
}

// mpv's "auto" can resolve differently at file start and after a runtime
// decoder restart (for example nvdec at start, vulkan-copy on a reinit), so
// remember which concrete decoder was actually in use and restore that one.
function noteHardwareDecoder() {
    if (hwdecForced)
        return;
    const current = hwdecName();
    if (!current || current === "no" || current.endsWith("-copy"))
        return;
    if (current === hwdecPin)
        return;
    hwdecPin = current;
    luma.config.set("hwdecPin", current);
}

function restoreHardwareDecoding() {
    if (!hwdecForced)
        return;
    hwdecForced = false;
    const option = original["hwdec"];
    if (hwdecPin && isAutoHwdec(option)) {
        // Pin the decoder the user actually had instead of letting mpv choose
        // again; the choice is verified on the next ticks.
        luma.mpv.setProperty("hwdec", hwdecPin);
        pinCheckAt = Date.now();
        return;
    }
    pinCheckAt = 0;
    restore("hwdec");
}

function restoreAll() {
    if (!active)
        return;
    removeFilter();
    restoreHardwareDecoding();
    restore("video-sync");
    restore("interpolation");
    active = false;
    filterActive = false;
    filterVerified = false;
    statusText = "";
    appliedSignature = "";
    pendingTarget = 0;
    original = {};
    lastTarget = 0;
    dropSample = null;
    droppedPerSecond = 0;
    retries = 0;
    pinCheckAt = 0;
    refreshStatsPage();
}

// Called when a file is about to load (fileOpened is emitted before mpv
// receives loadfile, while the previous file may still be playing). Sets the
// options for the upcoming chain, so the decoder starts in software mode with
// the filter already in place.
function apply(preparing) {
    const state = luma.media.state();
    if (!preparing && !state.hasVideo)
        return;

    if (!active) {
        remember("video-sync");
        remember("interpolation");
        remember("hwdec");
        active = true;
    }

    noteHardwareDecoder();

    const snapshot = luma.stats.snapshot();
    const mode = String(luma.config.get("mode", "display"));
    const interpolate = configBool("interpolation", true);
    const target = targetFps(snapshot);
    const signature = mode + ":" + target + ":" + (interpolate ? "1" : "0");

    // The chain survives file changes: only re-create it when the settings
    // changed or the previous file lost the filter. This keeps switching files
    // free of a filter reconfiguration.
    const sameChain = signature === appliedSignature && filterActive && interpolate;

    // The filter only accepts software frames. Switching hwdec restarts the
    // decoder with a seek, so do it once and only while frames are generated;
    // re-apply it if something else (for example the hwdec toggle shortcut)
    // turned hardware decoding back on. Doing it before the return paths keeps
    // a file switch from starting with the wrong decoder.
    if (interpolate && (!hwdecForced || !softwareFrames())) {
        hwdecForced = true;
        luma.mpv.setProperty("hwdec", "no");
    }

    if (!preparing) {
        if (signature === appliedSignature) {
            refreshStatsPage();
            return;
        }
    } else if (sameChain) {
        // Same settings and the filter is already in the chain: verify it on
        // the new file without touching the chain.
        verifyStartedAt = 0;
        filterVerified = false;
        pendingTarget = 0;
        refreshStatsPage();
        return;
    }

    appliedSignature = signature;
    lastTarget = target;
    statusText = "";
    pendingTarget = 0;
    verifyStartedAt = 0;
    dropSample = null;
    droppedPerSecond = 0;
    filterVerified = false;
    retries = 0;

    luma.mpv.setProperty("video-sync", mode === "display" ? "display-resample" : "audio");
    // mpv must not blend frames on its own on top of the generated ones.
    luma.mpv.setProperty("interpolation", "no");

    // Removing a filter costs blocking mpv commands; at file open there is
    // usually nothing to remove, so keep the hot path free of them.
    if (filterActive)
        removeFilter();
    filterActive = false;

    if (!interpolate) {
        // Nothing is generated, so leave decoding to the user's normal setting
        // (nvdec/vaapi) instead of keeping the software fallback.
        restoreHardwareDecoding();
        refreshStatsPage();
        return;
    }

    // Adding the filter now is safe before the new file starts; while an old
    // file still decodes on the GPU, wait for the decoder restart instead.
    if (softwareFrames() || (preparing && !state.hasVideo)) {
        addFilter(target);
    } else {
        pendingTarget = target;
        pendingSince = Date.now();
    }
    refreshStatsPage();
}

// Check that the filter chain really produces more frames than the source.
// mpv accepts "vf add" even when the filter cannot be configured, so the
// command result alone is not proof that frames are generated.
function monitorFilter() {
    const snapshot = luma.stats.snapshot();
    const source = Number(snapshot["container-fps"]);
    const output = Number(snapshot["estimated-vf-fps"]);
    const now = Date.now();
    if (!verifyStartedAt)
        verifyStartedAt = now;
    if (!(source > 0) || !(output > 0))
        return;

    const expectedMore = lastTarget > source * 1.2;
    if (expectedMore && !(output > source * 1.2)) {
        if (now - verifyStartedAt > 1500) {
            filterActive = false;
            filterVerified = false;
            statusText = luma.i18n.t("mpv disabled the filter; see the mpv log");
        }
        return;
    }
    filterVerified = true;

    const drops = Number(snapshot["frame-drop-count"]);
    if (!isFinite(drops) || now - verifyStartedAt < 2500)
        return;
    if (!dropSample) {
        dropSample = { drops: drops, time: now };
        return;
    }
    const seconds = (now - dropSample.time) / 1000;
    if (seconds < 1.5)
        return;
    droppedPerSecond = Math.max(0, (drops - dropSample.drops) / seconds);
    dropSample = { drops: drops, time: now };
}

// display-fps can become available only after the first frames. Reapply once
// when the detected refresh rate changes; don't rebuild the filter every tick.
function checkDisplayFps() {
    if (!active || String(luma.config.get("mode", "display")) !== "display")
        return;
    if (targetFps(luma.stats.snapshot()) !== lastTarget)
        apply(false);
}

function tick() {
    const state = luma.media.state();
    if (!state.hasVideo) {
        refreshStatsPage();
        return;
    }

    if (active)
        noteHardwareDecoder();
    if (pinCheckAt && !hwdecForced && Date.now() - pinCheckAt > 2000) {
        pinCheckAt = 0;
        const current = hwdecName();
        if (current === "no" || current === "") {
            // The remembered decoder is not available any more (for example the
            // GPU or driver changed); fall back to the user's setting once.
            const option = original["hwdec"];
            hwdecPin = "";
            luma.config.set("hwdecPin", "");
            if (option !== undefined && option !== "")
                luma.mpv.setProperty("hwdec", option);
        }
    }

    if (!active) {
        // The plugin was enabled while a file was already playing.
        apply(false);
        refreshStatsPage();
        return;
    }

    if (!configBool("interpolation", true)) {
        // Nothing to verify while the user keeps interpolation off.
    } else if (pendingTarget) {
        // Wait for the decoder restart requested by hwdec=no; afterwards the
        // filter chain sees software frames.
        if (softwareFrames() || Date.now() - pendingSince > 2500)
            addFilter(pendingTarget);
    } else if (filterActive) {
        monitorFilter();
    } else if (retries < 1 && lastTarget > 0 && softwareFrames()) {
        // mpv may have disabled the filter before the decoder restart finished;
        // give it one more chance on the running file.
        retries++;
        statusText = "";
        addFilter(lastTarget);
    }
    checkDisplayFps();
    refreshStatsPage();
}

function statsContent() {
    const snapshot = luma.stats.snapshot();
    const source = Number(snapshot["container-fps"]);
    const interpolate = configBool("interpolation", true);
    // estimated-vf-fps is a smoothed average: after the filter is removed mpv
    // keeps reporting the previous high rate for several seconds. Without a
    // filter the chain outputs exactly the source frames, so do not show the
    // stale value.
    const output = (filterActive && interpolate)
        ? Number(snapshot["estimated-vf-fps"]) : source;
    const display = displayFps(snapshot);
    const target = targetFps(snapshot);
    const drops = Number(snapshot["frame-drop-count"]);

    let frameState = luma.i18n.t("Inactive");
    if (interpolate) {
        if (pendingTarget || (filterActive && !filterVerified))
            frameState = luma.i18n.t("Starting");
        else if (filterVerified)
            frameState = luma.i18n.t("Active");
    }

    const content = [
        { type: "label", text: luma.i18n.t("Source FPS") + ": " + formatFps(source) },
        { type: "label", text: luma.i18n.t("Output FPS") + ": " + formatFps(output) },
        { type: "label", text: luma.i18n.t("Display FPS") + ": " + formatFps(display) },
        { type: "label", text: luma.i18n.t("Target FPS") + ": " + formatFps(target) },
        { type: "separator" },
        { type: "label", text: luma.i18n.t("Motion interpolation") + ": "
                       + (interpolate ? luma.i18n.t("Enabled") : luma.i18n.t("Disabled")) },
        { type: "label", text: luma.i18n.t("Frame generation") + ": " + frameState },
        { type: "label", text: luma.i18n.t("Filter") + ": "
                       + (filterActive ? "framerate" : luma.i18n.t("Inactive")) },
        { type: "label", text: luma.i18n.t("Mode") + ": "
                       + luma.i18n.t(String(luma.config.get("mode", "display"))) }
    ];
    if (filterVerified && isFinite(drops) && drops >= 0) {
        content.push({ type: "label", text: luma.i18n.t("Dropped frames") + ": "
                              + droppedPerSecond.toFixed(1) + "/s" });
    }
    if (statusText !== "")
        content.push({ type: "label", text: luma.i18n.t("Status") + ": " + statusText });
    return content;
}

function refreshStatsPage() {
    if (!luma || !luma.stats)
        return;
    const result = luma.stats.setPage(
        "smooth", luma.i18n.t("Smooth Motion stats"), statsContent());
    if (result && result.ok === false) {
        if (statsPageError !== result.error) {
            statsPageError = result.error;
            luma.log.warn(result.error);
        }
        return;
    }
    statsPageError = "";
}

// Assigned in Settings → Shortcuts (F9 by default) and declared in
// plugin.json under "shortcuts".
function toggleInterpolation() {
    setInterpolation(!configBool("interpolation", true));
}

function setInterpolation(enabled) {
    luma.config.set("interpolation", enabled);
    if (luma.ui && luma.ui.osd) {
        luma.ui.osd(enabled ? luma.i18n.t("Smooth Motion enabled")
                            : luma.i18n.t("Smooth Motion disabled"));
    }
    apply(false);
    refreshStatsPage();
}

function activate(lumaApi) {
    luma = lumaApi;
    luma.log.info("Smooth Motion loaded");
    hwdecPin = String(luma.config.get("hwdecPin", "")).trim().toLowerCase();
    if (hwdecPin === "no")
        hwdecPin = "";
    if (luma.shortcuts && luma.shortcuts.on)
        luma.shortcuts.on("toggle", () => { toggleInterpolation(); });
    luma.events.on("startup", () => { apply(false); });
    luma.events.on("fileOpened", () => { apply(true); refreshStatsPage(); });
    luma.events.on("mediaChanged", () => { refreshStatsPage(); });
    luma.events.on("settingsChanged", () => { apply(false); refreshStatsPage(); });
    luma.events.on("positionChanged", tick);
    // While paused there are no position ticks; still finish a deferred filter
    // add (e.g. after the decoder restart) when playback state changes.
    luma.events.on("pausedChanged", tick);
    apply(false);
    refreshStatsPage();
}

function deactivate() {
    restoreAll();
}
